function Pump{[Windows.Forms.Application]::DoEvents();Start-Sleep -Milliseconds 50}
function Native($path){return @{encoding='windows-utf16-le';units_hex=(-join $path.ToCharArray().ForEach({([int]$_).ToString('x4')}))}}
function Decode($path){Require ($path.encoding-eq'windows-utf16-le') 'Wrong response encoding';$s=$path.units_hex;$chars=for($i=0;$i-lt$s.Length;$i+=4){[char][Convert]::ToInt32($s.Substring($i,4),16)};$v=-join$chars;if($v.StartsWith('\\?\')){$v=$v.Substring(4)};return $v}
function Tree($w){return [Windows.Automation.AutomationElement]::FromHandle($w)}
function Matches($w,$name){$c=[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::NameProperty,$name);return (Tree $w).FindAll([Windows.Automation.TreeScope]::Descendants,$c)}
function Fields($w){$condition=[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::ControlTypeProperty,[Windows.Automation.ControlType]::Edit);return @((Tree $w).FindAll([Windows.Automation.TreeScope]::Descendants,$condition)|ForEach-Object {@{name=$_.Current.Name;bounds=@($_.Current.BoundingRectangle.X,$_.Current.BoundingRectangle.Y,$_.Current.BoundingRectangle.Width,$_.Current.BoundingRectangle.Height)}})}
function Named($w,$name){$deadline=[DateTime]::UtcNow.AddSeconds(20);do{$nodes=@((Matches $w $name)|Where-Object {$_.Current.ControlType-eq[Windows.Automation.ControlType]::Button-and$_.Current.IsEnabled});if($nodes.Count-eq1){return $nodes[0]};Pump}while([DateTime]::UtcNow-lt$deadline);[PickerNative]::Shot($w,(Join-Path $out 'missing-control.png'));throw ('Expected one enabled native button '+$name+'; count='+$nodes.Count)}
function Invoke($w,$name){$n=Named $w $name;$n.GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern).Invoke();Pump}
function Click($w,$name){$n=Named $w $name;$b=$n.Current.BoundingRectangle;$m=[regex]::Match([PickerNative]::Geometry($w),'client=(\d+)x(\d+) origin=(-?\d+),(-?\d+) dpi=(\d+)');Require $m.Success 'Missing client geometry';$x=[double]$m.Groups[3].Value;$y=[double]$m.Groups[4].Value;$scale=[double]$m.Groups[5].Value/96;Require ($b.Width-gt0-and$b.Height-gt0-and$b.Left-ge$x-and$b.Top-ge$y-and$b.Right-le($x+[double]$m.Groups[1].Value)-and$b.Bottom-le($y+[double]$m.Groups[2].Value)) 'Target outside actual native client';[PickerNative]::Click($w,($b.X+$b.Width/2-$x)/$scale,($b.Y+$b.Height/2-$y)/$scale);Pump}
function New-Picker($name,$mode,$directory,$filename='',$multiple=$false){
 $form=[Windows.Forms.Form]::new();$forms.Add($form);$form.Text='Owned cooperating caller '+$name;$form.Size=[Drawing.Size]::new(420,220);$form.Show();$form.Activate();Pump
 $request=@{mode=$mode;title='Ottrin picker audit '+$name;accept_label='Confirm selection';parent_window=('win32:{0:x}'-f$form.Handle.ToInt64());initial_directory=(Native $directory);filename=(Native $filename);multiple=$multiple}
 if($mode-ne'folder'){$request.filters=@(@{name='Text documents';patterns=@(@{kind='glob';value='*.txt'})});$request.current_filter=0}
 $start=[Diagnostics.ProcessStartInfo]::new($app,'picker --cancel-on-disconnect --renderer opengl');$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true;$start.StandardOutputEncoding=[Text.UTF8Encoding]::new($false);$start.StandardErrorEncoding=[Text.UTF8Encoding]::new($false);$clock=[Diagnostics.Stopwatch]::StartNew();$p=[Diagnostics.Process]::Start($start);$null=$p.Handle;$owned.Add($p);$stdout=$p.StandardOutput.ReadToEndAsync();$stderr=$p.StandardError.ReadToEndAsync();$p.StandardInput.AutoFlush=$true;$p.StandardInput.WriteLine(($request|ConvertTo-Json -Depth 12 -Compress))
 $deadline=[DateTime]::UtcNow.AddSeconds(40);$w=[IntPtr]::Zero;while($w-eq[IntPtr]::Zero){Require (-not$p.HasExited) 'Picker exited before real title mapped';Require ([DateTime]::UtcNow-lt$deadline) 'Actual titled picker window did not map';Pump;$w=[PickerNative]::Window($p.Id,('Ottrin — '+$request.title))}
 $mapped=$clock.Elapsed.TotalMilliseconds;[PickerNative]::Place($w);$null=Named $w 'Cancel';$null=Named $w ('Open '+$directory);if($mode-eq'open'-and$filename){Click $w $filename};$fields=Fields $w;Require (@($fields|Where-Object {$_.name-eq'Filter this folder'}).Count-eq1) 'Folder filter has no unique native accessible name';if($mode-ne'folder'){Require (@($fields|Where-Object {$_.name-eq'File name'}).Count-eq1) 'Filename has no unique native accessible name'};Require (@($fields|Where-Object {-not$_.name}).Count-eq0) 'Unnamed native editable picker control';$report.named_fields+=,@{case=$name;fields=$fields};Save
 $deadline=[DateTime]::UtcNow.AddSeconds(5);while([PickerNative]::GetWindow($w,4)-ne$form.Handle-and[DateTime]::UtcNow-lt$deadline){Pump};Require ([PickerNative]::GetWindow($w,4)-eq$form.Handle) 'Actual native caller ownership mismatch';Require ([PickerNative]::IsWindowEnabled($form.Handle)) 'Caller enabled state changed'
 $module=@($p.Modules|Where-Object {$_.FileName-ieq(Join-Path $bin 'opengl32.dll')});Require ($module.Count-eq1-and(Get-FileHash $module[0].FileName).Hash.ToLowerInvariant()-eq$manifest.'bin/opengl32.dll') 'Loaded OpenGL identity mismatch'
 return @{name=$name;process=$p;window=$w;caller=$form;stdout=$stdout;stderr=$stderr;request=$request;mapped_ms_upper_bound=$mapped;source_hash=(Get-FileHash $pref).Hash}
}
function Finish-Picker($c,$accept,$paths){$p=$c.process;$deadline=[DateTime]::UtcNow.AddSeconds(20);while(-not$p.HasExited-and[DateTime]::UtcNow-lt$deadline){Pump};Require $p.HasExited ('Picker did not finish '+$c.name);$p.WaitForExit();Require ($c.stdout.Wait(5000)-and$c.stderr.Wait(5000)) 'Picker streams not complete';[IO.File]::WriteAllText((Join-Path $out ($c.name+'.stdout')),$c.stdout.Result,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $out ($c.name+'.stderr')),$c.stderr.Result,[Text.UTF8Encoding]::new($false));Require ($p.ExitCode-eq0) ('Picker exit failed '+$c.name);$response=$c.stdout.Result|ConvertFrom-Json;Require ($response.accepted-eq$accept) 'Wrong accepted state';$actual=@($response.paths|ForEach-Object {Decode $_});$actualKey=(@($actual|Sort-Object)-join'|');$expectedKey=(@($paths|Sort-Object)-join'|');Require ($actualKey-ieq$expectedKey) 'Wrong native selected paths';Require ((Get-FileHash $pref).Hash-eq$c.source_hash) 'Picker changed main preferences';Require (@(Get-Process ottrin-indexd -ErrorAction SilentlyContinue).Count-eq0) 'Picker started index daemon';$value=@{case=$c.name;mode=$c.request.mode;request=$c.request;response=$response;normal_exit=$p.ExitCode;native_parent_verified=$true;caller_enabled_state_preserved=$true;mapped_ms_upper_bound=$c.mapped_ms_upper_bound;main_preferences_unchanged=$true;no_index=$true};if($c.idle){$value.idle=$c.idle};$report.cases+=,$value;Save;if(-not$c.caller.IsDisposed){$c.caller.Close();$c.caller.Dispose()}}
function Configure($theme,$custom=$false){$config.theme=$theme;$config.active_custom_theme=$null;$config.custom_themes=@();if($custom){$palette=@{titlebar=@(76,42,91,255);button_bg=@(36,107,132,255);window_border=@(220,170,66,255);window_border_width=2;app_radius=16;border_radius=10;button_radius=12;font_scale=1.2};$config.custom_themes=@(@{name='Audit Violet';base_preset='Ottrin';dark=$palette;light=$palette});$config.active_custom_theme='Audit Violet'};[IO.File]::WriteAllText($pref,($config|ConvertTo-Json -Depth 60),[Text.UTF8Encoding]::new($false))}
try{
 $id=[Security.Principal.WindowsIdentity]::GetCurrent();Require ($id.User.Value-eq$ExpectedSid) 'Wrong owned actor SID';Require (-not([Security.Principal.WindowsPrincipal]::new($id)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) 'Ordinary token required';$report.identity=@{sid=$ExpectedSid;administrator=$false;session=[Diagnostics.Process]::GetCurrentProcess().SessionId};Require ($report.identity.session-gt0) 'Interactive session required'
 Phase 'waiting for observed private desktop';$deadline=[DateTime]::UtcNow.AddMinutes(8);while(-not(Test-Path (Join-Path $out 'DESKTOP_READY.json'))){Require ([DateTime]::UtcNow-lt$deadline) 'Owned desktop readiness timeout';Start-Sleep -Milliseconds 200};$ready=Get-Content (Join-Path $out 'DESKTOP_READY.json') -Raw|ConvertFrom-Json;$owner=Get-Content 'C:\OttrinMsiCleanClientResults\OWNER.json' -Raw|ConvertFrom-Json;Require ($ready.sid-eq$ExpectedSid-and$ready.nonce-eq$owner.nonce) 'Readiness identity mismatch'
 $packageInput=Get-Content (Join-Path $Root 'application-input.json') -Raw|ConvertFrom-Json;foreach($file in $packageInput.files){Require ((Get-FileHash (Join-Path $Root $file.name)).Hash.ToLowerInvariant()-eq$file.sha256) 'Package input hash mismatch'};$report.package=$packageInput;$manifest=Get-Content (Join-Path $Root 'payload.json') -Raw|ConvertFrom-Json
 $install=Join-Path $env:LOCALAPPDATA 'Programs\Ottrin';$bin=Join-Path $install 'bin';$app=Join-Path $bin 'ottrin.exe';Require (-not(Test-Path $install)) 'Existing account installation retained';Phase 'install exact delivered NSIS';$null=Run (Join-Path $Root 'current-setup.exe') '/S' 'install';foreach($file in $manifest.PSObject.Properties){Require ((Get-FileHash (Join-Path $install $file.Name)).Hash.ToLowerInvariant()-eq$file.Value) ('Installed payload mismatch '+$file.Name)};Require (@(Get-ChildItem $install -Recurse -File).Count-eq59) 'Unexpected installed file count';$report.payload_files=58;Phase 'disable installer-created background service for index-independent picker cases';$report.index_remove=Run $app 'index service-remove' 'index-remove';Require (@(Get-Process ottrin-indexd -ErrorAction SilentlyContinue).Count-eq0) 'Supported removal left an index daemon'
 $corpus=Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'OttrinPickerAudit';Require (-not(Test-Path $corpus)) 'Existing source retained';$a=Join-Path $corpus 'Alpha';$b=Join-Path $corpus 'Beta';$null=[IO.Directory]::CreateDirectory($a);$null=[IO.Directory]::CreateDirectory((Join-Path $b 'Nested'))
 foreach($name in @('alpha.txt','beta.txt','target.txt','ignored.bin')){[IO.File]::WriteAllText((Join-Path $a $name),('Owned source '+$name),[Text.UTF8Encoding]::new($false))};$before=@{};foreach($file in Get-ChildItem $a -File){$before[$file.Name]=(Get-FileHash $file.FullName).Hash}
 $config=Get-Content (Join-Path $Root 'config-template.json') -Raw|ConvertFrom-Json;$config.bookmarks=@();$config.graphics_renderer='Native';$config.search.include_roots=@($corpus);$config.search.content_indexing_enabled=$false;$pref=Join-Path $env:APPDATA 'ottrin\config.json';Require (-not(Test-Path $pref)) 'Existing preferences retained';$null=[IO.Directory]::CreateDirectory((Split-Path $pref));Require (@(Get-Process ottrin-indexd -ErrorAction SilentlyContinue).Count-eq0) 'Unexpected index baseline'
 foreach($theme in @('Dark','Light')){
  Configure $theme;Phase ($theme+' process-cold open and idle');$c=New-Picker ($theme+'-cold') 'open' $a 'alpha.txt';$null=Named $c.window 'alpha.txt';Require ((Matches $c.window 'ignored.bin').Count-eq0) 'File-type filter did not hide binary';Start-Sleep -Seconds 1;$p=$c.process;$p.Refresh();$cpu=$p.TotalProcessorTime.TotalMilliseconds;$clock=[Diagnostics.Stopwatch]::StartNew();$deadline=[DateTime]::UtcNow.AddSeconds(30);while([DateTime]::UtcNow-lt$deadline){Pump};$p.Refresh();$c.idle=@{seconds=$clock.Elapsed.TotalSeconds;cpu_percent_one_core=($p.TotalProcessorTime.TotalMilliseconds-$cpu)/10/$clock.Elapsed.TotalSeconds;working_set_bytes=$p.WorkingSet64;private_bytes=$p.PrivateMemorySize64;scope='Visible ready picker; process-cold start with OS caches retained, no index process'};[PickerNative]::Shot($c.window,(Join-Path $out ($theme+'-picker.png')));Invoke $c.window 'Confirm selection';Finish-Picker $c $true @((Join-Path $a 'alpha.txt'))
  Phase ($theme+' folder and request-over-preference');$c=New-Picker ($theme+'-folder') 'folder' $b;Invoke $c.window 'Confirm selection';Finish-Picker $c $true @($b)
  $c=New-Picker ($theme+'-repeated') 'open' $a 'beta.txt';Invoke $c.window 'Confirm selection';Finish-Picker $c $true @((Join-Path $a 'beta.txt'))
 }
 Configure 'Dark';Phase 'multiple selection';$c=New-Picker 'multiple' 'open' $a '' $true;Click $c.window 'alpha.txt';try{[PickerAuditInput]::Control($true);Click $c.window 'beta.txt'}finally{[PickerAuditInput]::Control($false)};Invoke $c.window 'Confirm selection';Finish-Picker $c $true @((Join-Path $a 'alpha.txt'),(Join-Path $a 'beta.txt'))
 Phase 'new Save does not write';$target=Join-Path $a 'new-save.txt';$c=New-Picker 'save-new' 'save' $a 'new-save.txt';Invoke $c.window 'Confirm selection';Finish-Picker $c $true @($target);Require (-not(Test-Path $target)) 'Picker created Save output'
 Phase 'overwrite requires explicit confirmation and preserves bytes';$c=New-Picker 'save-overwrite' 'save' $a 'target.txt';Invoke $c.window 'Confirm selection';$null=Named $c.window 'Replace';Require ((Get-FileHash (Join-Path $a 'target.txt')).Hash-eq$before['target.txt']) 'Overwrite prompt changed bytes';[PickerNative]::Shot($c.window,(Join-Path $out 'overwrite-confirmation.png'));Invoke $c.window 'Replace';Finish-Picker $c $true @((Join-Path $a 'target.txt'));Require ((Get-FileHash (Join-Path $a 'target.txt')).Hash-eq$before['target.txt']) 'Save acceptance changed existing bytes'
 Phase 'actual custom theme';Configure 'Dark' $true;$c=New-Picker 'custom-theme' 'open' $a 'alpha.txt';$file=Join-Path $out 'custom-picker.png';[PickerNative]::Shot($c.window,$file);$report.custom_pixels=@{titlebar=[PickerAuditInput]::Pixels($file,76,42,91);button=[PickerAuditInput]::Pixels($file,36,107,132);border=[PickerAuditInput]::Pixels($file,220,170,66)};Require ($report.custom_pixels.titlebar-gt100-and$report.custom_pixels.button-gt100-and$report.custom_pixels.border-gt100) 'Custom theme did not reach actual picker roles';$report.custom_parameters=@{font_scale=1.2;window_radius=16;button_radius=12;window_border_width=2};$editCondition=[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::ControlTypeProperty,[Windows.Automation.ControlType]::Edit);$report.picker_edit_controls=@((Tree $c.window).FindAll([Windows.Automation.TreeScope]::Descendants,$editCondition)|ForEach-Object {@{name=$_.Current.Name;bounds=@($_.Current.BoundingRectangle.X,$_.Current.BoundingRectangle.Y,$_.Current.BoundingRectangle.Width,$_.Current.BoundingRectangle.Height)}});Invoke $c.window 'Edit location';$locationFields=Fields $c.window;Require (@($locationFields|Where-Object {$_.name-eq'Location'}).Count-eq1) 'Location field has no unique native accessible name';Require (@($locationFields|Where-Object {-not$_.name}).Count-eq0) 'Unnamed editable location control';$report.native_location_fields=$locationFields;Invoke $c.window 'Cancel';Finish-Picker $c $false @()
 Configure 'Dark';Phase 'caller disconnect and owner loss';$c=New-Picker 'disconnect' 'open' $a;$c.process.StandardInput.Close();Finish-Picker $c $false @();$c=New-Picker 'owner-loss' 'open' $a;$c.caller.Close();$c.caller.Dispose();Finish-Picker $c $false @()
 Phase 'two independent simultaneous requests';$one=New-Picker 'concurrent-one' 'open' $a;$two=New-Picker 'concurrent-two' 'open' $b;Invoke $one.window 'Cancel';Finish-Picker $one $false @();Require (-not$two.process.HasExited) 'Cancelling first request closed second';Require ([PickerNative]::Window($two.process.Id,('Ottrin — '+$two.request.title))-eq$two.window) 'Other native chooser disappeared';Invoke $two.window 'Cancel';Finish-Picker $two $false @();$report.concurrent_independent=$true
 foreach($file in Get-ChildItem $a -File){Require ($before.ContainsKey($file.Name)-and(Get-FileHash $file.FullName).Hash-eq$before[$file.Name]) 'Source data changed'};Require (@(Get-ChildItem $a -File).Count-eq$before.Count) 'Unexpected source output';$report.source_bytes_preserved=$true
 $saved=(Get-FileHash $pref).Hash;Phase 'supported uninstall';$uninstaller=Join-Path $out 'owned-uninstall.exe';Copy-Item (Join-Path $install 'Uninstall.exe') $uninstaller;$null=Run $uninstaller ('/S _?='+$install) 'uninstall';Remove-Item $uninstaller;Require (-not(Test-Path $install)) 'Installation remains';Require ((Get-FileHash $pref).Hash-eq$saved) 'Uninstall changed preferences';$report.preferences_preserved_by_removal=$true;$final='pass within native cooperating-picker/resource scope; actual captures require review'
}catch{$report.error=$_.Exception.Message;$report.stack=$_.ScriptStackTrace}
